import { Router } from "@angular/router";
import { computed, inject } from "@angular/core";
import {
  patchState,
  signalStore,
  withComputed,
  withMethods,
  withState,
} from "@ngrx/signals";
import { User, userStore } from "src/app/store/userStore";
import { AuthService } from "../services/auth.service";
import { DialogService } from "src/app/shared/services/dialog.service";

interface AuthState {
  currentUser: User | null;
  isAuthenticated: boolean;
  authState: "idle" | "authenticating" | "authenticated" | "error";
}

const initialAuthState: AuthState = {
  currentUser: null,
  isAuthenticated: false,
  authState: "idle",
};

export const authStore = signalStore(
  { providedIn: "root" },
  withState(initialAuthState),
  withComputed(({ currentUser }) => ({
    isAdmin: computed(() => currentUser()?.role === "admin"),
  })),
  withMethods(
    (
      store,
      router = inject(Router),
      authService = inject(AuthService),
      dialogService = inject(DialogService),
    ) => ({
      login(username: string, password: string): void {
        dialogService.showDialog();
        patchState(store, { authState: "authenticating" });

        authService.login({ username, password }).subscribe({
          next: (user: User) => {
            patchState(store, {
              currentUser: user,
              isAuthenticated: true,
              authState: "authenticated",
            });
            localStorage.setItem("token", user.token);
            router.navigate(["/dashboard"]);
          },
          error: () => {
            patchState(store, { authState: "error" });
          },
          complete: () => dialogService.hideDialog(),
        });
      },

      logout(): void {
        patchState(store, {
          currentUser: null,
          isAuthenticated: false,
          authState: "idle",
        });
      },

      setCurrentUser(user: User): void {
        patchState(store, {
          currentUser: user,
          isAuthenticated: true,
          authState: "authenticated",
        });
      },
    }),
  ),
);
